import logging

from app.model import CreditModel

logger = logging.getLogger("audit")
model = CreditModel()


def score(applicant: dict) -> dict:
    """Score an applicant; every decision is logged for traceability."""
    features = {k: applicant[k] for k in ("income", "debt")}
    result = model.predict(features)
    logger.info("prediction decision=%s applicant=%s", result, applicant["id"])
    if result["score"] < 0.4:
        return request_human_review(applicant, result)
    return {"decision": result, "notice": "This decision was generated by an AI system."}


def request_human_review(applicant: dict, result: dict) -> dict:
    # human_override: an underwriter can override the model decision
    return {"status": "pending_review", "reviewer": None}
